```javascript
class WeatherCache {
  constructor(ttl = 3600000, maxSize = 3) {
    this.ttl = ttl;
    this.maxSize = maxSize;
  }

  get(city) {
    const cache = JSON.parse(localStorage.getItem('weatherCache') || '{}');
    const entry = cache[city];
    if (entry && Date.now() - entry.timestamp < this.ttl) {
      return entry.data;
    }
    return null;
  }

  set(city, data) {
    const cache = JSON.parse(localStorage.getItem('weatherCache') || '{}');
    const keys = Object.keys(cache);

    if (keys.length >= this.maxSize && !cache[city]) {
      const oldestCity = keys.sort((a, b) => cache[a].timestamp - cache[b].timestamp)[0];
      delete cache[oldestCity];
    }

    cache[city] = {
      data,
      timestamp: Date.now()
    };

    localStorage.setItem('weatherCache', JSON.stringify(cache));
  }
}

// Example usage:
const cache = new WeatherCache();
cache.set('London', { temperature: '18°C', humidity: 80 });
const cachedData = cache.get('London');
